585 /// Returns a pointer to the specified item in the list if it exists, 0 if not found.
 586 AkForceInline T* Exists(ARG_T in_Item) const
587 {
588 Iterator it = FindEx( in_Item );
589 return ( it != End() ) ? it.pItem : 0;
590 }
