1149 HashTableArray oldArray;
1150 oldArray.Transfer(m_table);
1151
1152 if (m_table.GrowArray(uNewSize))
1153 {
1154 for (AkUInt32 i = 0; i < uNewSize; i++)
1155 m_table.AddLast(NULL);
