1162 T_MAPSTRUCT* pNextItem = LIST_POLICY::Next(pItem);
1163 {
1164 AkHashType uiTable = AkHash(KEY_POLICY::Key(pItem)) % uNewSize;
1165 LIST_POLICY::Next(pItem) = m_table[uiTable];
1166 m_table[uiTable] = pItem;
1167 }
1168 pItem = pNextItem;
