 219 AkUInt32 GetIndex(T_ITEM* in_pItem) const
220 {
221 if (this->m_pItems && this->m_uLength > 0)
222 {
223 AkUInt32 index = (AkUInt32)(in_pItem - this->m_pItems);
224 if ((this->m_pItems \+ index) == in_pItem)
