259 {
260 T_ITEM * pItem = BinarySearch(in_key, out_bFound);
261 if (pItem)
262 {
263 unsigned int uIdx = (unsigned int)(pItem - this->m_pItems);
264 pItem = this->Insert(uIdx);
265 }
266 else
267 {
268 pItem = this->AddLast();
269 }
270
271 return pItem;
272 }
