283 {
284 T_ITEM * pItem = BinarySearch(in_key, out_bExists);
285 if (!out_bExists)
286 {
287 if (pItem)
288 {
289 unsigned int uIdx = (unsigned int)(pItem - this->m_pItems);
290 pItem = this->Insert(uIdx);
