285
286 while (itB != in_B.End() || itA != io_A.End())
287 {
288 if ( itB != in_B.End() && (itA == io_A.End() || TComparePolicy::Lesser(&io_A, *itB, *itA)))
289 {
290 *itRes = *itB;
291 ++itB;
292 }
293 else if (itB == in_B.End() || TComparePolicy::Lesser(&io_A, *itA,*itB) )
294 {
295 *itRes = *itA;
296 ++itA;
297 }
298 else //if ( *itA == *itC)
299 {
300 *itRes = *itA;
301 ++itA;
302 ++itB;
303 }
304
305 ++itRes;
306 }
307
308 io_A.Transfer(result);
