296 {
297 if (pInstance == NULL)
298 {
299 pInstance = (Instance*)pInstance->TAlloc::Alloc(sizeof(Instance));
300
301 if (pInstance == nullptr)
302 return AK_Fail;
303
304 AkPlacementNew(pInstance) Instance();
305
306 return AK_Success;
307 }
308 else
309 return AK_Fail;
310 }
311
312 // Term the DB.
