1720 bool SetNormal()
1721 {
1722 //m_pNormal = (B-A) cross (C-A); normalize
1723 Ak3DVector a = p2 - p1;
1724 Ak3DVector b = p4 - p1;
1725
1726 N = Ak3DVector(a.Y*b.Z \- a.Z*b.Y, -(a.X*b.Z \- a.Z*b.X), a.X*b.Y \- a.Y*b.X);
1727
1728 AkReal32 len = N.Length();
1729 AKASSERT(len > 0.f);
1730
1731 if (len > 0)
1732 {
1733 N /= len;
1734 }
1735 else
1736 {
1737 return false;
1738 }
1739
1740 return true;
