208 /// Set the name of a thread: see http://msdn.microsoft.com/en-us/library/xcb2z8hs.aspx
 209 inline void AkSetThreadName( AkThread in_threadHnd, DWORD in_dwThreadID, LPCSTR in_szThreadName )
210 {
211 AK_UNUSEDVAR(in_threadHnd);
212 const DWORD MS_VC_EXCEPTION=0x406D1388;
213
214 #pragma pack(push,8)
215 typedef struct tagTHREADNAME_INFO
216 {
217 DWORD dwType;
218 LPCSTR szName;
219 DWORD dwThreadID;
220 DWORD dwFlags;
221 } THREADNAME_INFO;
222 #pragma pack(pop)
223
224 THREADNAME_INFO info;
225 info.dwType = 0x1000;
226 info.szName = in_szThreadName;
227 info.dwThreadID = in_dwThreadID;
228 info.dwFlags = 0;
229
230 __try
231 {
232 RaiseException( MS_VC_EXCEPTION, 0, sizeof(info)/sizeof(ULONG_PTR), (ULONG_PTR*)&info );
233 }
234 #pragma warning(suppress: 6312 6322)
235 __except(EXCEPTION_CONTINUE_EXECUTION)
236 {
237 }
238
239 #if defined(AK_XBOX) || defined(_GAMING_DESKTOP) // also applicable on Windows when Win7 support is dropped. SetThreadDescription is a Win10 only API
240 wchar_t wszThreadName[32];
241 AkUInt32 maxStrLen = (sizeof(wszThreadName) / sizeof(wchar_t)) - 1;
242 AkUInt32 nameStrLen = AkMin((int)strlen(in_szThreadName), maxStrLen);
243 MultiByteToWideChar(CP_UTF8, 0, in_szThreadName, nameStrLen, wszThreadName, maxStrLen);
244 wszThreadName[nameStrLen] = '\0';
245 SetThreadDescription(in_threadHnd, wszThreadName);
246 #endif
247 }
