249 /// Platform Independent Helper
 250 inline void AkCreateThread( 
251 AkThreadRoutine pStartRoutine, // Thread routine.
252 void * pParams, // Routine params.
253 const AkThreadProperties & in_threadProperties, // Properties. NULL for default.
254 AkThread * out_pThread, // Returned thread handle.
255 const char * in_szThreadName ) // Opt thread name.
256 {
257 AKASSERT( out_pThread != NULL );
258 AKASSERT( (in_threadProperties.nPriority >= THREAD_PRIORITY_LOWEST && in_threadProperties.nPriority <= THREAD_PRIORITY_HIGHEST)
259 || ( in_threadProperties.nPriority == THREAD_PRIORITY_TIME_CRITICAL )
260 || ( in_threadProperties.nPriority == THREAD_MODE_BACKGROUND_BEGIN ) );
261
262 DWORD dwThreadID;
263 *out_pThread = ::CreateThread( NULL, // No security attributes
264 in_threadProperties.uStackSize, // StackSize (0 uses system default)
265 pStartRoutine, // Thread start routine
266 pParams, // Thread function parameter
267 CREATE_SUSPENDED, // Creation flags: create suspended so we can set priority/affinity before starting
268 &dwThreadID );
269
270 // ::CreateThread() return NULL if it fails.
271 if ( !*out_pThread )
272 {
273 AkClearThread( out_pThread );
274 return;
275 }
276
277 // Set thread name.
278 if (in_szThreadName)
279 {
280 AkSetThreadName(*out_pThread, dwThreadID, in_szThreadName);
281 }
282
283 // Set properties.
284 if ( !::SetThreadPriority( *out_pThread, in_threadProperties.nPriority ) &&
285 in_threadProperties.nPriority != THREAD_MODE_BACKGROUND_BEGIN )
286 {
287 AKASSERT( !"Failed setting thread priority" );
288 AkCloseThread( out_pThread );
289 AkClearThread(out_pThread);
290 return;
291 }
292 if (in_threadProperties.dwAffinityMask)
293 {
294 AkUInt32 dwAffinityMask = in_threadProperties.dwAffinityMask;
295 DWORD_PTR procAffinity, sysAffinity;
296 if (::GetProcessAffinityMask(::GetCurrentProcess(), &procAffinity, &sysAffinity))
297 {
298 // To avoid errors in SetThreadAffinityMask, make sure the user-supplied mask is a subset of what is allowed by the process
299 dwAffinityMask &= procAffinity;
300 }
301 if (!::SetThreadAffinityMask(*out_pThread, dwAffinityMask))
302 {
303 AKASSERT(!"Failed setting thread affinity mask");
304 AkCloseThread(out_pThread);
305 AkClearThread(out_pThread);
306 return;
307 }
308 }
309
310 // Thread is ready, start it up.
311 if (!::ResumeThread(*out_pThread))
312 {
313 AKASSERT(!"Failed to start the thread");
314 AkCloseThread(out_pThread);
315 AkClearThread(out_pThread);
316 return;
317 }
318 }
