479 /// Output a debug message on the console (variadic function).
480 /// Use MaxSize to specify the size to reserve for the message.
481 /// Warning: On Win32, OutputDebugMsgV with wchar_t will truncate the string
482 /// to MaxSize.
483 template <int MaxSize = 256>
 484 inline void OutputDebugMsgV(const wchar_t* in_pszFmt, ...)
485 {
486 // No equivalent of snprintf for wide string so truncate if necessary
487 // vswprintf returns the number of characters written and not the numbers
488 // that would be written
489
490 wchar_t* msg = (wchar_t*)AkAlloca(MaxSize * sizeof(wchar_t));
491 msg[MaxSize - 1] = '\0';
492
493 va_list args;
494 va_start(args, in_pszFmt);
495 vswprintf(msg, MaxSize, in_pszFmt, args);
496 va_end(args);
497
498 OutputDebugMsg(msg);
499 }
500
501 /// Output a debug message on the console (variadic function).
502 /// Use MaxSize to specify the expected size of the message.
503 /// If the required size is superior to MaxSize, a new string
504 /// will be allocated on the stack with the required size.
505 template <int MaxSize = 256>
 506 inline void OutputDebugMsgV(const char* in_pszFmt, ...)
507 {
508 int size = 0;
509 {
510 // Try with a reasonable guess first
511 char msg[MaxSize];
512 msg[MaxSize - 1] = '\0';
513
514 va_list args;
515 va_start(args, in_pszFmt);
516 size = vsnprintf(msg, MaxSize, in_pszFmt, args);
517 va_end(args);
518
519 // If it was enough, print to debug log
520 if (0 <= size && size <= MaxSize)
521 {
522 OutputDebugMsg(msg);
523 return;
524 }
525 }
526
527 // Else, we need more memory to prevent truncation
528 {
529 // size + 1 more char for the last '\0'
530 size++;
531
532 char* msg = (char*)AkAlloca((size) * sizeof(char));
533 msg[size - 1] = '\0';
534
535 va_list args;
536 va_start(args, in_pszFmt);
537 vsnprintf(msg, size, in_pszFmt, args);
538 va_end(args);
539
540 OutputDebugMsg(msg);
541 }
542 }
543
544 #else
545 inline void OutputDebugMsg(const wchar_t*){}
546 inline void OutputDebugMsg(const char*){}
547
548 template <int MaxSize = 0>
549 inline void OutputDebugMsgV(const wchar_t*, ...) {}
550
551 template <int MaxSize = 0>
552 inline void OutputDebugMsgV(const char*, ...) {}
